/**
 * Join ordering of the LMDB pipeline when the sketch-based estimator is not ready: plans must be connected and the cost
 * of a pattern must not be discounted for a bound variable that no available index can seek on.
 */
class LmdbIndexAwareJoinOptimizerTest {

	private static final String EX = "http://example.org/";

	/**
	 * F binds {@code ?b}. Pattern O ({@code ?x ?y ?b}) can only use {@code ?b} as a bound object, pattern S
	 * ({@code ?b ex:pS ?z}) can seek on it as a subject.
	 */
	private static final String INDEX_QUERY = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT * WHERE { ?a ex:pF ?b . ?x ?y ?b . ?b ex:pS ?z . }";

	@Test
	void connectedPatternIsPickedBeforeCheaperDisconnectedPattern() {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pA ?b . ?b ex:pB ?c . ?c ex:pD ?d . }", "spoc,posc,ospc");

		assertThat(predicates(plan)).containsExactly(EX + "pA", EX + "pB", EX + "pD");
	}

	@Test
	void boundObjectWithoutObjectIndexDoesNotMakePatternLookCheap() {
		TupleExpr plan = optimize(INDEX_QUERY, "spoc,posc");

		assertThat(predicates(plan))
				.as("S can seek on the bound subject; O cannot seek on its bound object without an object index")
				.containsExactly(EX + "pF", EX + "pS", null);
	}

	@Test
	void boundObjectWithObjectIndexKeepsItsDiscount() {
		TupleExpr plan = optimize(INDEX_QUERY, "spoc,posc,ospc");

		assertThat(predicates(plan)).as("with an ospc index O seeks on its bound object and stays cheapest")
				.containsExactly(EX + "pF", null, EX + "pS");
	}

	@Test
	void indexAwareOrderingAlsoAppliesWhenTheQueryContainsValues() {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { VALUES ?a { ex:v1 } ?a ex:pF ?b . ?x ?y ?b . ?b ex:pS ?z . }", "spoc,posc");

		assertThat(predicates(plan)).containsExactly(EX + "pF", EX + "pS", null);
	}

	@Test
	void recordedCostIsTheDiscountFreeCostWhenTheBoundObjectCanBeSeeked() {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pF ?b . ?x ?y ?b . }", "spoc,posc,ospc");

		// (cardinality 100 + 5) ^ (2 unbound / 3 non-constant variables)
		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(Math.pow(105, 2.0 / 3.0), within(0.01));
	}

	@Test
	void recordedCostUndoesTheDiscountWhenTheBoundObjectCannotBeSeeked() {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pF ?b . ?x ?y ?b . }", "spoc,posc");

		// the bound object cannot be seeked on, so the base discount is undone: (105 ^ (2/3)) * 105 ^ (1/3)
		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(105.0, within(0.01));
	}

	private static TupleExpr optimize(String query, String indexes) {
		LmdbStandardQueryOptimizerPipeline pipeline = pipeline(new SimulatedIndexStatistics(indexes));
		List<QueryOptimizer> optimizers = new ArrayList<>();
		pipeline.getOptimizers().forEach(optimizers::add);
		assertThat(optimizers.stream().map(o -> o.getClass().getSimpleName())).contains("LmdbIndexAwareJoinOptimizer");

		TupleExpr expr = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		for (QueryOptimizer optimizer : optimizers) {
			optimizer.optimize(expr, null, EmptyBindingSet.getInstance());
		}
		return expr;
	}

	private static LmdbStandardQueryOptimizerPipeline pipeline(SimulatedIndexStatistics statistics) {
		TripleSource tripleSource = new EmptyTripleSource();
		EvaluationStrategy strategy = new DefaultEvaluationStrategyFactory().createEvaluationStrategy((Dataset) null,
				tripleSource, statistics, QueryExecutionPolicy.EXPERIMENTAL);
		return new LmdbStandardQueryOptimizerPipeline(strategy, tripleSource, statistics);
	}

	/** Predicates of all statement patterns in plan order; {@code null} for a variable predicate. */
	private static List<String> predicates(TupleExpr plan) {
		List<String> predicates = new ArrayList<>();
		plan.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				predicates.add(node.getPredicateVar().hasValue() ? node.getPredicateVar().getValue().stringValue()
						: null);
			}
		});
		return predicates;
	}

	private static StatementPattern pattern(TupleExpr plan, String predicate) {
		List<StatementPattern> found = new ArrayList<>();
		plan.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				String p = node.getPredicateVar().hasValue() ? node.getPredicateVar().getValue().stringValue() : null;
				if ((predicate == null && p == null) || (predicate != null && predicate.equals(p))) {
					found.add(node);
				}
			}
		});
		assertThat(found).as(plan.toString()).hasSize(1);
		return found.get(0);
	}

	/**
	 * Statistics without sketches whose index access prefix is derived from a configured index list, like the real
	 * fallback.
	 */
	private static final class SimulatedIndexStatistics extends LmdbEvaluationStatistics {

		private final String[] indexes;

		SimulatedIndexStatistics(String indexes) {
			super(mock(ValueStore.class), mock(TripleStore.class), null);
			this.indexes = indexes.split(",");
		}

		@Override
		public double getCardinality(TupleExpr expr) {
			if (expr instanceof StatementPattern pattern) {
				if (!pattern.getPredicateVar().hasValue()) {
					return 100;
				}
				return switch (pattern.getPredicateVar().getValue().stringValue().substring(EX.length())) {
				case "pF", "pA" -> 2;
				case "pB" -> 1000;
				case "pD" -> 3;
				case "pS" -> 5000;
				default -> 10;
				};
			}
			return super.getCardinality(expr);
		}

		@Override
		int fallbackAccessPrefixLength(StatementPattern pattern, Set<String> boundVars) {
			int best = 0;
			for (String index : indexes) {
				int length = 0;
				for (char component : index.toCharArray()) {
					Var var = switch (component) {
					case 's' -> pattern.getSubjectVar();
					case 'p' -> pattern.getPredicateVar();
					case 'o' -> pattern.getObjectVar();
					default -> pattern.getContextVar();
					};
					boolean fixed = var != null
							&& (var.hasValue() || (var.getName() != null && boundVars.contains(var.getName())));
					if (!fixed) {
						break;
					}
					length++;
				}
				best = Math.max(best, length);
			}
			return best;
		}
	}

	private static final class EmptyTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return SimpleValueFactory.getInstance();
		}
	}
}
